    ('b9362982-59ac-5a15-aebe-de733a8f6cb3'::uuid, 5549, 'Hyundai', 'Tucson', 2022, 'Drew Dorian', 'published'::public.task_status, 'new_mmp'::public.task_kind, null, '', null, '', timestamptz '2021-02-26T00:00:00-05:00', timestamptz '2021-02-26T00:00:00-05:00'),
    ('b3a20d68-cf42-5fae-9e6a-52f66b063231'::uuid, 5550, 'Kia', 'Niro', 2021, 'Eric Stafford', 'published'::public.task_status, 'new_mmp'::public.task_kind, null, '', null, '', timestamptz '2021-02-25T00:00:00-05:00', timestamptz '2021-02-25T00:00:00-05:00'),
